fieldValues.fieldValue:
={{
  ['ABANDONED', 'WAITING_PAYMENT', 'DELAYED', 'CANCELED', 'EXPIRED'].includes(
    String($json.current_status || '').trim().toUpperCase()
  )
  &&
  Number($json.last_step_sent ?? 0) > 0
    ? Number($('Receber Evento do Ingresso').item.json.price || 0)
    : ($json.recovered_revenue ?? null)
}}

conditions.leftValue:
={{
  ['ABANDONED', 'WAITING_PAYMENT'].includes(
    String($json.current_status || '').trim().toUpperCase()
  )
  &&
  (
    $json.last_event_created_at === null ||
    $json.last_event_created_at === undefined ||
    Number($('Receber Evento do Ingresso').item.json.event_created_at) >= Number($json.last_event_created_at)
  )
}}

